{"code": "import os

def check_image_files(directory):
    issues = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            size = os.path.getsize(filepath)
            if size < 1000:  # Less than 1KB is suspicious for an image
                issues.append((filepath, size))
    return issues

print("Checking for suspiciously small image files...")
for path, size in check_image_files('data_small/Training'):
    print(f"{path}: {size} bytes")

for path, size in check_image_files('data_small/Testing'):
    print(f"{path}: {size} bytes")"}

